// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public { c = new airPort(); }

    // Fuzz the 'from' address and ensure we still check behavior when _tos is empty.
    // The property: for ANY inputs, calling transfer with an EMPTY _tos MUST NOT succeed (the correct C reverts),
    // while the mutant allowing >=0 will succeed for some inputs. We therefore assert that the call does NOT return true.
    function testFuzz_property(address from) public {
        // Keep domain wide: allow any from (but avoid the zero-address for clarity if desired).
        // Construct an empty recipients array to trigger the difference.
        address[] memory tos = new address[](0);

        bool ok;
        try c.transfer(from, address(0x1234), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // ASSERTION: correct contract always reverts (ok == false) for empty _tos
        // The mutant that changed the require to `_tos.length >= 0` will make ok == true for some inputs,
        // causing this assertion to fail on the mutant.
        assertTrue(!ok);
    }
}
